    @Fuzz
    public void testBugReproduction(boolean hasDataset,
                         @InRange(minInt = 0, maxInt = 7) int rows,
                         @InRange(minInt = 0, maxInt = 6) int cols,
                         @InRange(minDouble = 0, maxDouble = 100) double value,
